package ai.taskforge.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { private final byte[] key; public JwtService(@Value("${taskforge.jwt-secret}") String secret){key=Arrays.copyOf(secret.getBytes(StandardCharsets.UTF_8),32);} public String issue(UUID id,String email,String role){return Jwts.builder().subject(id.toString()).claim("email",email).claim("role",role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(Keys.hmacShaKeyFor(key)).compact();} public UUID subject(String token){return UUID.fromString(Jwts.parser().verifyWith(Keys.hmacShaKeyFor(key)).build().parseSignedClaims(token).getPayload().getSubject());} }
